use genewars_runtime::{turret_projectile::plan_mule_turret_aim,physics_tables::PhysicsTables};
use std::{fs,path::Path};
fn main(){let w=std::env::args().nth(1).unwrap();let w=Path::new(&w);let physics=PhysicsTables::from_mapped_bytes(&fs::read(w.join("angles.bin")).unwrap(),&fs::read(w.join("bounce.bin")).unwrap()).unwrap();let map=fs::read(w.join("map.bin")).unwrap();let input=fs::read(w.join("input.bin")).unwrap();let mut out=Vec::new();for (index,r)in input.chunks_exact(191).enumerate(){let result=plan_mule_turret_aim(r[..67].try_into().unwrap(),r[67..].try_into().unwrap(),&map,&physics).unwrap_or_else(|e|panic!("{index}:{e}"));for n in result.angles{out.extend(n.to_le_bytes())}for n in result.forecast_position{out.extend(n.to_le_bytes())}out.extend(result.forecast_height.to_le_bytes());out.extend(result.launch_height.to_le_bytes());}fs::write(w.join("actual.bin"),out).unwrap();println!("256 aim geometries");}
